package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class TwoStepChangeStoriesTest {
 @Test public void all41472StoriesUsePublicEventsAndLearnerChoices(){Set<String> signatures=new HashSet<>();Set<String> numeric=new HashSet<>();Set<Integer> operators=new HashSet<>();for(int c=0;c<2;c++)for(int start=1000;start<=9000;start+=100)for(int first:TwoStepChangeStories.CHANGES)for(int second:TwoStepChangeStories.CHANGES)for(int op=0;op<4;op++){boolean a=(op&1)==0,b=(op&2)==0;int middle=start+(a?first:-first),result=middle+(b?second:-second);Question q=TwoStepChangeStories.make(c,start,first,a,second,b);assertTrue(signatures.add(q.signature()));numeric.add(start+":"+first+":"+second+":"+op);operators.add(op);q.answers=new String[]{"poison"};q.expression="poison";assertArrayEquals(new int[]{start,first,second,a?1:0,b?1:0,middle,result},TwoStepChangeStories.read(q));assertTrue(new Checker().check(q,List.of(),List.of(""+result)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(result+1))).status);HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(4,p.size());assertTrue(p.restore(null,q.id).entries.stream().allMatch(String::isEmpty));assertTrue(p.step(0).accepts(a?"+":"-"));assertFalse(p.step(0).accepts(a?"-":"+"));assertTrue(p.step(1).accepts(""+middle));assertTrue(p.step(2).accepts(b?"+":"-"));assertTrue(p.step(3).accepts(""+result));for(int i:new int[]{1,3})assertFalse(p.step(i).before.matches("(?s).*[0-9].*"));assertTrue(q.choices.isEmpty());}assertEquals(41472,signatures.size());assertEquals(20736,numeric.size());assertEquals(4,operators.size());}
 @Test public void realFreshSupplyFullPublicHistoryOldestAndGradeBoundary(){Generator g=new Generator(new Random(146));CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",TwoStepChangeStories.ID,4);List<String> history=new ArrayList<>();Set<String> ops=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next(TwoStepChangeStories.ID,history,false,limits);assertFalse(history.contains(q.signature()));history.add(q.signature());int[] v=TwoStepChangeStories.read(q);ops.add(v[3]+":"+v[4]);}assertEquals(4,ops.size());Map<String,Integer> full=new LinkedHashMap<>();for(int i=0;i<TwoStepChangeStories.COUNT;i++)assertNull(full.put(TwoStepChangeStories.indexed(i).signature(),i));assertEquals(full.keySet().iterator().next(),TwoStepChangeStories.next(new Random(1),limits,full).signature());Learning.Profile profile=new Learning.Profile();GlobalCurriculum.chooseCountry(profile,"GB");GlobalCurriculum.choosePack(profile,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(profile).inGrade(TwoStepChangeStories.ID,4));assertFalse(GlobalCurriculum.pack(profile).inGrade(TwoStepChangeStories.ID,3));}
 @Test public void publicDomainBoundariesAndMalformedConditions(){for(int[] values:new int[][]{{0,0,0},{9999,0,0},{1,1,0}}){Question q=TwoStepChangeStories.make(0,values[0],values[1],false,values[2],true);assertNotNull(TwoStepChangeStories.read(q));}Question q=TwoStepChangeStories.make(0,1000,7,false,25,false);for(String prompt:List.of(q.prompt.replace("처음: 1000","처음: 0"),q.prompt.replace("처음: 1000","처음: 9999").replace("나눠 줬어요","더 받았어요"),"스티커\n지금 몇 개인가요?")){Question bad=TwoStepChangeStories.make(0,1000,7,false,25,false);bad.prompt=prompt;bad.answers=new String[]{"0"};assertNull(TwoStepChangeStories.read(bad));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(bad,List.of(),List.of("0")).status);}for(String s:List.of("","1e3","-1","10000","3+4"))assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of(s)).status);}
}
